public Mono<MetricBoundary> findByMetric(String metric) {
    Objects.requireNonNull(metric, "metric");
    return databaseClient.sql("SELECT metric, min, max FROM telemetry.metric_boundaries WHERE metric = :metric")
        .bind("metric", Parameter.from(metric))
        .fetch()
        .all()
        .map(R2dbcMetricBoundaryRepository::toBoundary)
        .next();
}

private static MetricBoundary toBoundary(Map<String, Object> row) {
    return new MetricBoundary(
        (String) row.get("metric"),
        ((Number) row.get("min")).doubleValue(),
        ((Number) row.get("max")).doubleValue());
}
